head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.GUBUN_MONTH = "1";            // 조회구분: 기준월(단월) — 전월·전전월 열을 보인다 (원본 rdo_gubun CodeValue "1")
scwin.ISUR_LP_TP_LP = "02";         // 회사구분: 제3자 LP (그 밖 "01" 은 발행회사 — 원본 cmb_instlp_select BindColVal)
scwin.TOTAL_ROW_TEXT = "합계(평균)";  // 합계 행 판정 — 이 행은 bg_orange (원본 bgcolor decode(COM_ABBRV,'합계(평균)','#FFCC99') — 규칙 40·43)

// 원본 : ULDSTF08061.gfm (순자본비율(ETN))
/*
 * 화면 동작
 *  - 화면을 열면 기준년 콤보 6개·제3자 LP·보증인 목록을 채우고, 월 콤보는 이번 달로 둔다. 자동 조회는 하지 않는다(원본과 같음).
 *  - 위 구역 : 발행인/제3자 LP 의 순자본비율을 기준월(회사구분·연·월) 또는 기간(회사구분·회사·시작 연월~종료 연월)으로 조회한다.
 *  - 아래 구역 : 보증인의 자기자본비율을 기준월(연·월) 또는 기간(보증인·시작 연월~종료 연월)으로 조회한다.
 *  - 기준월 조회에서만 전월·전전월 열을 보이고, 구역마다 목록을 엑셀로 내려받는다.
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF08061/ULDSTF08061.md (§번호는 이 문서의 절)
 */

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 30
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08061.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 30
 * @description 로딩 — 조회구분·회사구분 기본값과 이번 달 → 조회 영역 Enter 키 → 기준년·LP·보증인 목록 → 기준년 기본값(첫 항목) → 기간 회사 콤보 → 구분별 콤보 활성 상태.
 * 자동 조회는 하지 않는다. (원본 gform onload → fn_init — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 조회구분은 기준월, 회사구분은 발행회사 (원본 rdo_gubun1/2.CodeValue = "1", 회사구분 콤보 index 0)
    dma_cond1.set("gubun", scwin.GUBUN_MONTH);
    dma_cond1.set("isurLpTp1", "01");
    dma_cond1.set("isurLpTp2", "01");
    dma_cond2.set("gubun", scwin.GUBUN_MONTH);

    // 2) 월 콤보 6개는 이번 달 (원본 cGetToday("yyyymmdd").substring(4, 6) → setObjectValue(cmb_month1~6))
    const month = $c.date.getServerDateTime("yyyyMMdd").substring(4, 6);
    ["month1", "month2", "month3"].forEach(key => dma_cond1.set(key, month));
    ["month4", "month5", "month6"].forEach(key => dma_cond2.set(key, month));

    // 3) 조회 영역 Enter 키 (규칙 22) — 구역마다 그 구역의 조회
    $c.win.setEnterKeyEvent(panel_Top_1, scwin.btn_search1_onclick);
    $c.win.setEnterKeyEvent(panel_Top_2, scwin.btn_search2_onclick);

    // 4) 콤보 목록 — 기준년(6개 공용 1회), 제3자 LP, 보증인 (원본 dts_year1~6 동기 로드 · dts_lp · dts_srty)
    await scwin.selectYearList();
    await scwin.selectLpCdList();
    await scwin.selectSrtyCdList();

    // 5) 기준년 6개는 첫 항목 (원본 콤보 index 0) · 기간 회사 콤보는 발행회사 목록 (원본 cmb_inst_lp.ComboDataID = "dts_inst")
    scwin.setDefaultYear();
    scwin.setInstLpList(dma_cond1.get("isurLpTp2"));

    // 6) 구분별 콤보 활성 상태 (원본 fn_change_gubun1("1") · fn_change_gubun2("1"))
    scwin.changeGubun1(scwin.GUBUN_MONTH);
    scwin.changeGubun2(scwin.GUBUN_MONTH);
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.rdo_gubun1_onviewchange
 * @author Inswave
 * @date 2026. 10. 30
 * @description 발행인/제3자 LP 조회구분(기준월·기간) 변경 — 구분에 맞는 콤보만 쓸 수 있게 한다. (원본 rdo_gubun1 OnSelChange → fn_change_gubun1)
 * @param {Object} info 변경 정보
 * @returns
 * @hidden N
 */
scwin.rdo_gubun1_onviewchange = function (info) {
    try {
        scwin.changeGubun1(info.newValue);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08061.rdo_gubun1_onviewchange" });
    }
};

/**
 * @method
 * @name scwin.rdo_gubun2_onviewchange
 * @author Inswave
 * @date 2026. 10. 30
 * @description 보증인 조회구분(기준월·기간) 변경 — 구분에 맞는 콤보만 쓸 수 있게 한다. (원본 rdo_gubun2 OnSelChange → fn_change_gubun2)
 * @param {Object} info 변경 정보
 * @returns
 * @hidden N
 */
scwin.rdo_gubun2_onviewchange = function (info) {
    try {
        scwin.changeGubun2(info.newValue);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08061.rdo_gubun2_onviewchange" });
    }
};

/**
 * @method
 * @name scwin.cmb_instlp_select2_onviewchange
 * @author Inswave
 * @date 2026. 10. 30
 * @description 기간 회사구분(발행회사·제3자 LP) 변경 — 회사 콤보 목록을 바꾸고 "전체" 로 되돌린다. (원본 cmb_instlp_select2 OnSelChange)
 * @param {Object} info 변경 정보
 * @returns
 * @hidden N
 */
scwin.cmb_instlp_select2_onviewchange = function (info) {
    try {
        scwin.setInstLpList(info.newValue);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08061.cmb_instlp_select2_onviewchange" });
    }
};

/**
 * @method
 * @name scwin.btn_search1_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 발행인/제3자 LP 조회 버튼 클릭 (위 조회 영역 Enter 키도 이 핸들러) (원본 btn_search1 onclick → fn_list_sync1)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_search1_onclick = async function (e) {
    try {
        await scwin.selectIsurLpNcr();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08061.btn_search1_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_search2_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 보증인 조회 버튼 클릭 (아래 조회 영역 Enter 키도 이 핸들러) (원본 btn_search2 onclick → fn_list_sync2)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_search2_onclick = async function (e) {
    try {
        await scwin.selectSrtyCapRto();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08061.btn_search2_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_excel1_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 발행사/LP 순자본비율 엑셀다운로드 버튼 클릭 (원본 btn_excel1 onclick — doLogSave 삭제, §6.5)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_excel1_onclick = async function (e) {
    try {
        await scwin.excelDown1();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08061.btn_excel1_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_excel2_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 보증인 자기자본비율 엑셀다운로드 버튼 클릭 (원본 btn_excel2 onclick — doLogSave 삭제, §6.5)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_excel2_onclick = async function (e) {
    try {
        await scwin.excelDown2();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08061.btn_excel2_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectYearList
 * @author Inswave
 * @date 2026. 10. 30
 * @description 기준년 콤보 목록 조회 — 기준년 콤보 6개가 itemset 으로 dlt_year 를 함께 쓴다. (원본 fn_init dts_year1~6 selectElwNcrYear — §5.1)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectYearList = async function () {
    const sbmOptions = {
        id : "sbm_selectYearList",
        method : "get",
        action : "/api/listing/lstproc/etn/ncr/select-list-year",
        target : "dlt_year=body",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    return result.responseJSON?.success === true;    // 실패 안내는 공통 오류 핸들러(원본 OnLoadError → alert_error)
};

/**
 * @method
 * @name scwin.selectLpCdList
 * @author Inswave
 * @date 2026. 10. 30
 * @description ETN 유동성공급자(LP) 목록 조회 — 기간 회사구분이 제3자 LP 일 때 회사 콤보 원천. (원본 fn_init dts_lp listLPCd&For=R — §5.2)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectLpCdList = async function () {
    const sbmOptions = {
        id : "sbm_selectLpCdList",
        method : "get",
        action : "/api/listing/lstproc/etn/code/list-lpCd",
        target : "dlt_lpCd=body",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return false;
    return result.responseJSON?.success === true;
};

/**
 * @method
 * @name scwin.selectSrtyCdList
 * @author Inswave
 * @date 2026. 10. 30
 * @description ETN 보증인 목록 조회 — 보증인 콤보는 itemset 으로 dlt_srtyCd 에 바인딩돼 있다. (원본 fn_init dts_srty listSrtyCd&For=R — §5.3)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectSrtyCdList = async function () {
    const sbmOptions = {
        id : "sbm_selectSrtyCdList",
        method : "get",
        action : "/api/listing/lstproc/etn/code/list-srtyCd",
        target : "dlt_srtyCd=body",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return false;
    return result.responseJSON?.success === true;
};

/**
 * @method
 * @name scwin.selectIsurLpNcr
 * @author Inswave
 * @date 2026. 10. 30
 * @description 발행사/LP 순자본비율 조회 — 조회구분에 따라 요청을 만들고, 기준월이면 전월·전전월 열을 보이고 기간이면 숨긴다.
 * 기준월: 회사구분 + 시작 연월만, 기간: 회사구분 + 시작·종료 연월 + 회사. (원본 fn_list_sync1 searchIsurLpNcrDetailList — §5.4)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectIsurLpNcr = async function () {
    const cond = dma_cond1.getJSON();
    const isMonth = (cond.gubun === scwin.GUBUN_MONTH);
    const isurLpTp = isMonth ? cond.isurLpTp1 : cond.isurLpTp2;

    // 원본은 URL 인자를 덧붙였다 — 기준월은 TO_YYMM·ISUR_LP_CD 를 보내지 않았으므로 빈 값으로 둔다
    dma_isurLpNcrReq.setJSON({
        gubun : (isurLpTp === scwin.ISUR_LP_TP_LP) ? "lp" : "isur",
        fromYymm : isMonth ? (cond.year1 + cond.month1) : (cond.year2 + cond.month2),
        toYymm : isMonth ? "" : (cond.year3 + cond.month3),
        isurLpCd : isMonth ? "" : (cond.isurLpCd ?? "")
    });

    // 전월·전전월은 단월 조회에서만 채워진다 (원본 grid_list1.ColumnProp('NCR_PRE1','Show'))
    grd_list1.setColumnVisible("ncrPre1", isMonth);
    grd_list1.setColumnVisible("ncrPre2", isMonth);

    const sbmOptions = {
        id : "sbm_selectIsurLpNcr",
        method : "get",
        action : "/api/listing/lstproc/etn/ncr/select-list-isur-lp-ncr",
        ref : "dma_isurLpNcrReq",
        target : "dlt_isurLpNcr=body",
        gridview : "grd_list1",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return false;
    return result.responseJSON?.success === true;    // 실패 안내는 공통 오류 핸들러(원본 dts_list_1 OnLoadError → alert_error)
};

/**
 * @method
 * @name scwin.selectSrtyCapRto
 * @author Inswave
 * @date 2026. 10. 30
 * @description 보증인 자기자본비율 조회 — 조회구분에 따라 요청을 만들고, 기준월이면 전월·전전월 열을 보이고 기간이면 숨긴다.
 * 기준월: 시작 연월만, 기간: 시작·종료 연월 + 보증인. (원본 fn_list_sync2 searchSrtyCapRatioDetailList — §5.5)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectSrtyCapRto = async function () {
    const cond = dma_cond2.getJSON();
    const isMonth = (cond.gubun === scwin.GUBUN_MONTH);

    dma_srtyCapRtoReq.setJSON({
        fromYymm : isMonth ? (cond.year4 + cond.month4) : (cond.year5 + cond.month5),
        toYymm : isMonth ? "" : (cond.year6 + cond.month6),
        srtyCd : isMonth ? "" : (cond.srtyCd ?? "")
    });

    // 전월·전전월은 단월 조회에서만 채워진다 (원본 grid_list2.ColumnProp('CAP_RTO_PRE1','Show'))
    grd_list2.setColumnVisible("capRtoPre1", isMonth);
    grd_list2.setColumnVisible("capRtoPre2", isMonth);

    const sbmOptions = {
        id : "sbm_selectSrtyCapRto",
        method : "get",
        action : "/api/listing/lstproc/etn/ncr/select-list-srty-cap-rto",
        ref : "dma_srtyCapRtoReq",
        target : "dlt_srtyCapRto=body",
        gridview : "grd_list2",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return false;
    return result.responseJSON?.success === true;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.setDefaultYear
 * @author Inswave
 * @date 2026. 10. 30
 * @description 기준년 콤보 6개를 목록의 첫 항목으로 둔다. 목록이 비면 그대로 둔다. (원본 콤보 index 0 — §6.1)
 * @returns
 * @hidden N
 */
scwin.setDefaultYear = function () {
    if (dlt_year.getRowCount() === 0) return;

    const year = dlt_year.getCellData(0, "value");
    ["year1", "year2", "year3"].forEach(key => dma_cond1.set(key, year));
    ["year4", "year5", "year6"].forEach(key => dma_cond2.set(key, year));
};

/**
 * @method
 * @name scwin.setInstLpList
 * @author Inswave
 * @date 2026. 10. 30
 * @description 기간 회사 콤보 목록을 회사구분에 맞춘다 — 제3자 LP 면 LP 목록, 발행회사면 발행회사 목록. 선택은 "전체" 로 되돌린다.
 * (원본 cmb_inst_lp.ComboDataID = "dts_lp" / "dts_inst" · index = 0 — §6.2)
 * @param {String} isurLpTp 기간 회사구분(01 발행회사, 02 제3자 LP)
 * @returns
 * @hidden N
 */
scwin.setInstLpList = function (isurLpTp) {
    // TODO: 발행회사 목록 API(원본 listIsurCd&For=R)가 명세에 없다 — 받기 전까지 발행회사는 "전체" 만 고를 수 있다 (§10 #1)
    const isLp = (isurLpTp === scwin.ISUR_LP_TP_LP);
    dlt_instLp.setJSON(isLp ? dlt_lpCd.getAllJSON() : []);
    dma_cond1.set("isurLpCd", "");
};

/**
 * @method
 * @name scwin.changeGubun1
 * @author Inswave
 * @date 2026. 10. 30
 * @description 발행인/제3자 LP 조회구분에 맞춰 콤보를 쓸 수 있게 한다 — 기준월: 회사구분1·연·월, 기간: 회사구분2·회사·시작/종료 연월. (원본 fn_change_gubun1 — §6.3)
 * @param {String} gubun 조회구분(1 기준월, 2 기간)
 * @returns
 * @hidden N
 */
scwin.changeGubun1 = function (gubun) {
    const isMonth = (gubun === scwin.GUBUN_MONTH);
    [cmb_instlp_select1, cmb_year1, cmb_month1].forEach(comp => comp.setDisabled(!isMonth));
    [cmb_instlp_select2, cmb_inst_lp, cmb_year2, cmb_month2, cmb_year3, cmb_month3].forEach(comp => comp.setDisabled(isMonth));
};

/**
 * @method
 * @name scwin.changeGubun2
 * @author Inswave
 * @date 2026. 10. 30
 * @description 보증인 조회구분에 맞춰 콤보를 쓸 수 있게 한다 — 기준월: 연·월, 기간: 보증인·시작/종료 연월. (원본 fn_change_gubun2 — §6.3)
 * @param {String} gubun 조회구분(1 기준월, 2 기간)
 * @returns
 * @hidden N
 */
scwin.changeGubun2 = function (gubun) {
    const isMonth = (gubun === scwin.GUBUN_MONTH);
    [cmb_year4, cmb_month4].forEach(comp => comp.setDisabled(!isMonth));
    [cmb_srty, cmb_year5, cmb_month5, cmb_year6, cmb_month6].forEach(comp => comp.setDisabled(isMonth));
};

/**
 * @method
 * @name scwin.excelDown1
 * @author Inswave
 * @date 2026. 10. 30
 * @description 발행사/LP 순자본비율 목록을 엑셀로 내려받는다. 0건 안내는 공통 함수가 한다. (원본 fn_ExcelDown1 GridToExcel("ETN 발행사/LP (영업용)순자본비율", "", "8") — §6.5)
 * @returns
 * @hidden N
 */
scwin.excelDown1 = async function () {
    await $c.data.downloadGridViewExcel(grd_list1, {
        // 파일명 {menuId}_{이름}_{yyyyMMddHHmmss}.xlsx (전환 규칙 42) — 원본 제목의 "/" 는 파일명에 쓸 수 없어 뺐다
        fileName : $c.win.getProgramId() + "_ETN발행사LP순자본비율_" + $c.date.getServerDateTime("yyyyMMddHHmmss") + ".xlsx",
        sheetName : "sheet1"
    });
};

