/**
 * @method
 * @name scwin.fmtIsurLpNcr
 * @author Inswave
 * @date 2026. 10. 30
 * @description 발행사/LP 순자본비율 목록 customFormatter(전 열) — 값은 그대로 두고, 회사명/연월이 "합계(평균)" 인 행에 bg_orange 배경을 붙인다.
 * 동기 함수 — async 금지(규칙 43). (원본 bgcolor decode(COM_ABBRV,'합계(평균)','#FFCC99','default') — §6.4)
 * @param {String} data 원본 값
 * @param {String} formattedData 표시 형식이 적용된 값
 * @param {Number} rowIndex 화면 행 번호 — 같은 행 회사명/연월은 그리드 기준으로 읽는다
 * @param {Number} colIndex 컬럼 번호
 * @returns {String} 셀에 표시할 값(HTML 없음)
 * @hidden N
 */
scwin.fmtIsurLpNcr = function (data, formattedData, rowIndex, colIndex) {
    if (String(this.getCellData(rowIndex, "comAbbrv") ?? "") === scwin.TOTAL_ROW_TEXT) {
        this.setCellClass(rowIndex, colIndex, "bg_orange");
    } else {
        this.removeCellClass(rowIndex, colIndex);
    }
    return formattedData;
};

/**
 * @method
 * @name scwin.fmtSrtyCapRto
 * @author Inswave
 * @date 2026. 10. 30
 * @description 보증인 자기자본비율 목록 customFormatter(전 열) — 값은 그대로 두고, 회사명/연월(srtyAbbrv)이 "합계(평균)" 인 행에 bg_orange 배경을 붙인다.
 * 원본은 이 그리드에 없는 COM_ABBRV 로 판정해 색이 나오지 않았다(§8 #3 고침). 동기 함수 — async 금지(규칙 43). (§6.4)
 * @param {String} data 원본 값
 * @param {String} formattedData 표시 형식이 적용된 값
 * @param {Number} rowIndex 화면 행 번호 — 같은 행 회사명/연월은 그리드 기준으로 읽는다
 * @param {Number} colIndex 컬럼 번호
 * @returns {String} 셀에 표시할 값(HTML 없음)
 * @hidden N
 */
scwin.fmtSrtyCapRto = function (data, formattedData, rowIndex, colIndex) {
    if (String(this.getCellData(rowIndex, "srtyAbbrv") ?? "") === scwin.TOTAL_ROW_TEXT) {
        this.setCellClass(rowIndex, colIndex, "bg_orange");
    } else {
        this.removeCellClass(rowIndex, colIndex);
    }
    return formattedData;
};
